template<class T> class std::shared_ptr;

// Creating a shared_ptr
auto ptr = std::make_shared<T>(constructor_args...);

// Using unique_ptr
std::unique_ptr<T> uptr = std::make_unique<T>(constructor_args...);

// Weak pointer to observe shared ownership
std::weak_ptr<T> wptr = ptr;

code_example:
#include <iostream>
#include <memory>

class Widget {
public:
    Widget() { std::cout << "Widget constructed" << std::endl; }
    ~Widget() { std::cout << "Widget destroyed" << std::endl; }
    void display() { std::cout << "Displaying Widget" << std::endl; }
};

int main() {
    // Create a shared_ptr managing a Widget object
    auto widgetPtr = std::make_shared<Widget>();
    {
        // Create a weak_ptr observing the shared_ptr
        std::weak_ptr<Widget> weakWidget = widgetPtr;
        if (auto shared = weakWidget.lock()) {
            shared->display();
        }
    }
    // Reset shared_ptr, Widget will be destroyed if no other owners
    widgetPtr.reset();
    return 0;
}
